def earliest_not_so_rainy_day(n, x, y, a):
    stack = []
    result = [-1] * n

    for i in range(n):
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()

        if stack:
            left = stack[-1]
            if i - left - 1 == x:
                result[left] = i

        stack.append(i)

    stack.clear()

    for i in range(n - 1, -1, -1):
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()

        if stack:
            right = stack[-1]
            if right - i - 1 == y:
                result[right] = i

        stack.append(i)

    return min([i for i, val in enumerate(result) if val != -1])

